function bulk_csv_rows(string $path): array {
    $fh=fopen($path,'rb'); if(!$fh) throw new RuntimeException('Could not read upload.');
    $headers=fgetcsv($fh); $expected=['spot_name','category_tag','riddle_text','youtube_video_id','correct_answer','reward_type','reward_value','timer_ttl_minutes'];
    $headers=array_map(static fn($v)=>strtolower(trim((string)$v)), $headers?:[]);
    if($headers!==$expected) throw new InvalidArgumentException('CSV headers must exactly match the eight-column specification.');
    $rows=[]; while(($row=fgetcsv($fh))!==false){if(count(array_filter($row,static fn($v)=>trim((string)$v)!==''))===0)continue; if(count($row)!==8)throw new InvalidArgumentException('Every CSV row must contain eight columns.'); $r=array_combine($expected,$row); if(trim((string)$r['spot_name'])==='')throw new InvalidArgumentException('spot_name is required.'); $r['reward_type']=strtoupper(trim((string)$r['reward_type'])); if(!in_array($r['reward_type'],['PROMO_CASH','COUPON_VOUCHER'],true))throw new InvalidArgumentException('reward_type must be PROMO_CASH or COUPON_VOUCHER.'); if(!preg_match('/^\d{1,12}(\.\d{1,2})?$/',trim((string)$r['reward_value'])))throw new InvalidArgumentException('reward_value is invalid.'); $ttl=trim((string)$r['timer_ttl_minutes']); if($ttl!==''&&(!ctype_digit($ttl)||(int)$ttl<1||(int)$ttl>10080))throw new InvalidArgumentException('timer_ttl_minutes must be 1-10080.'); $rows[]=$r; }
    fclose($fh); if(!$rows)throw new InvalidArgumentException('The CSV contains no data rows.'); if(count($rows)>5000)throw new InvalidArgumentException('Maximum 5,000 rows per batch.'); return $rows;
}
function batch_card_svg(string $spot,string $payload): string { $spot=htmlspecialchars($spot,ENT_QUOTES,'UTF-8'); $payload=htmlspecialchars($payload,ENT_QUOTES,'UTF-8'); return '<svg xmlns="http://www.w3.org/2000/svg" width="600" height="720" viewBox="0 0 600 720"><rect width="600" height="720" fill="white"/><rect x="40" y="40" width="520" height="520" fill="none" stroke="black" stroke-width="8"/><path d="M80 80h120v120H80zM400 80h120v120H400zM80 400h120v120H80zM260 260h80v80h-80zM380 260h40v40h-40zM460 340h60v60h-60zM260 420h50v50h-50z" fill="black"/><text x="300" y="610" text-anchor="middle" font-family="Arial" font-size="24">'.$spot.'</text><text x="300" y="650" text-anchor="middle" font-family="Arial" font-size="13">'.substr($payload,0,80).'</text></svg>'; }

if (isset($_GET['download_template'])) {
    header('Content-Type: text/csv; charset=utf-8');
