    fputcsv($out,['spot_name','category_tag','riddle_text','youtube_video_id','correct_answer','reward_type','reward_value','timer_ttl_minutes']);
    fputcsv($out,['Patna Mall Rack 1','shopping','Find the hidden clue','dQw4w9WgXcQ','Watch','PROMO_CASH','15.00','30']);
    exit;
}

if(($_SERVER['REQUEST_METHOD']??'GET')==='GET' && input('download')){
    require_permission('qr.download'); $id=(int)input('download'); $b=db()->prepare('SELECT * FROM qr_batches WHERE id=?');$b->execute([$id]);$batch=$b->fetch();if(!$batch){http_response_code(404);exit('Batch not found');}
    $items=db()->prepare('SELECT * FROM qr_batch_items WHERE batch_id=? ORDER BY id');$items->execute([$id]);$rows=$items->fetchAll();$tmp=sys_get_temp_dir().'/hunter-batch-'.bin2hex(random_bytes(8));mkdir($tmp,0700,true);$csv=fopen($tmp.'/mapping.csv','wb');fputcsv($csv,['Spot_ID','Spot_Name','Category','Encrypted_URL','Status']);$zip=new ZipArchive();$zip->open($tmp.'/batch.zip',ZipArchive::CREATE);
    foreach($rows as $r){fputcsv($csv,[$r['spot_id'],$r['spot_name'],$r['category_tag'],$r['encrypted_url'],$r['status']]);$zip->addFromString('qr-'.$r['spot_id'].'.svg',batch_card_svg($r['spot_name'],$r['encrypted_url']));}fclose($csv);$zip->addFile($tmp.'/mapping.csv','mapping.csv');$zip->close();audit_log((int)admin()['id'],'QR_BATCH_DOWNLOAD','qr_batches',(string)$id,null,['items'=>count($rows)]);header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_-]/','_', $batch['batch_code']).'.zip"');readfile($tmp.'/batch.zip');exit;
}

if(is_post()){verify_csrf(); try{$pdo=db();$hunt=(int)input('hunt_id');$loc=(int)input('location_id');$check=$pdo->prepare('SELECT h.id,l.id FROM hunts h JOIN hunt_locations l ON l.hunt_id=h.id WHERE h.id=? AND l.id=?');$check->execute([$hunt,$loc]);if(!$check->fetch())throw new InvalidArgumentException('Select a valid Hunt and location.');$mode=strtoupper((string)input('generation_mode'));$rows=$mode==='UPLOAD'?bulk_csv_rows($_FILES['csv']['tmp_name']??''):[];$qty=(int)input('quantity');if($mode==='AUTO_COUNT'){if($qty<1||$qty>5000)throw new InvalidArgumentException('Quantity must be 1-5000.');for($i=1;$i<=$qty;$i++)$rows[]=['spot_name'=>'Spot '.$i,'category_tag'=>trim((string)input('category_tag')),'riddle_text'=>trim((string)input('riddle_text')),'youtube_video_id'=>trim((string)input('youtube_video_id')),'correct_answer'=>'','reward_type'=>strtoupper((string)input('reward_type')),'reward_value'=>trim((string)input('reward_value')),'timer_ttl_minutes'=>trim((string)input('timer_ttl_minutes'))];}
    if(count($rows)>5000)throw new InvalidArgumentException('Maximum 5,000 rows per batch.');$pdo->beginTransaction();$code='BATCH-'.strtoupper(bin2hex(random_bytes(5)));$pdo->prepare('INSERT INTO qr_batches(batch_code,batch_title,category,question_bank_category,generation_mode,quantity,scan_frequency,reward_type,reward_value,hunt_id,location_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$code,trim((string)input('batch_title'))?:$code,strtoupper((string)input('category')?:'VIDEO_PAHELI'),trim((string)input('question_bank_category'))?:null,$mode,count($rows),strtoupper((string)input('scan_frequency')?:'PER_DEVICE'),strtoupper((string)($rows[0]['reward_type']??'PROMO_CASH')),(string)($rows[0]['reward_value']??0),$hunt,$loc,admin()['id']]);$batchId=(int)$pdo->lastInsertId();$qr=$pdo->prepare('INSERT INTO hunt_qr_codes(hunt_id,location_id,token_hash,label,status,created_by) VALUES(?,?,?,? ,"ACTIVE",?)');$item=$pdo->prepare('INSERT INTO qr_batch_items(batch_id,spot_id,spot_name,category_tag,riddle_text,youtube_video_id,correct_answer_hash,reward_type,reward_value,timer_ttl_minutes,qr_code_id,encrypted_url) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');foreach($rows as $n=>$r){$token=bin2hex(random_bytes(32));$qr->execute([$hunt,$loc,hash('sha256',$token),$r['spot_name'],admin()['id']]);$qrId=(int)$pdo->lastInsertId();$spotId=$code.'-'.str_pad((string)($n+1),5,'0',STR_PAD_LEFT);$url='app://campaign/riddle?id='.$spotId.'&t='.$token;$ans=trim((string)$r['correct_answer']);$item->execute([$batchId,$spotId,trim((string)$r['spot_name']),trim((string)$r['category_tag']),trim((string)$r['riddle_text']),trim((string)$r['youtube_video_id'])?:null,$ans===''?null:hash('sha256',strtolower($ans)),strtoupper((string)$r['reward_type']),(string)$r['reward_value'],trim((string)$r['timer_ttl_minutes'])?:null,$qrId,$url]);}audit_log((int)admin()['id'],'QR_BATCH_CREATED','qr_batches',(string)$batchId,null,['batch_code'=>$code,'quantity'=>count($rows),'mode'=>$mode]);$pdo->commit();flash('success','Bulk QR batch created. Download the ZIP from the batch list.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('/admin/qr/bulk.php');}

$hunts=db()->query('SELECT id,title FROM hunts WHERE status IN ("ACTIVE","DRAFT") ORDER BY title')->fetchAll();$batches=db()->query('SELECT b.*,h.title hunt,l.name location,(SELECT COUNT(*) FROM qr_batch_items i WHERE i.batch_id=b.id) item_count,(SELECT COUNT(*) FROM qr_batch_items i WHERE i.batch_id=b.id AND i.status="SCANNED") scanned_count FROM qr_batches b LEFT JOIN hunts h ON h.id=b.hunt_id LEFT JOIN hunt_locations l ON l.id=b.location_id ORDER BY b.id DESC')->fetchAll();$pageTitle='Bulk QR generator';$pageSubtitle='Validated Excel/CSV import and controlled batch downloads';require APP_ROOT.'/includes/header.php';
?>
